package main

import (
	"errors"
	"fmt"
	"time"
)

var ErrBusy = errors.New("busy")
var ErrCanceled = errors.New("canceled")

// throttle ensures fn runs at most `limit` times per second.
// Returns ErrBusy if the limit is reached, ErrCanceled if the limiter was stopped.
// Returns handle (runs fn subject to the limit) and cancel (stops the limiter).
func throttle(limit int, fn func()) (handle func() error, cancel func()) {
	tokens := make(chan struct{}, limit)
	cancelCh := make(chan struct{})

	for range limit {
		tokens <- struct{}{}
	}

	go func() {
		ticker := time.NewTicker(time.Second)
		defer func() {
			ticker.Stop()
		}()
		for {
			select {
			case <-ticker.C:
				for range limit {
					select {
					case tokens <- struct{}{}:
					default:
					}
				}
			case <-cancelCh:
				return
			}
		}
	}()

	handle = func() error {
		select {
		case <-cancelCh:
			return ErrCanceled
		default:
			select {
			case <-tokens:
				fn()
				return nil
			default:
				return ErrBusy
			}
		}
	}

	cancel = func() {
		close(cancelCh)
	}

	return handle, cancel
}

func main() {
	handle, cancel := throttle(5, work)
	defer cancel()

	const n = 8
	var nOK, nErr int
	for range n {
		err := handle()
		if err == nil {
			nOK += 1
		} else {
			nErr += 1
		}
	}

	fmt.Printf("%d calls: %d OK, %d busy\n", n, nOK, nErr)
}

func work() {
	fmt.Print(".")
}

